canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean {
  const requiredRole = route.data['role'];
  const currentUser = this.authService.currentUser;

  if (!currentUser || currentUser.role !== requiredRole) {
    return false;
  }
  return true;
}

